head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > useFilterList]<br/>GridView 컴포넌트의 Header Column 에 FilterList 기능을 활성화할지 설정합니다.",
    "validation" : [
        "useFilter=true 인 Header Column 에서 동작하며 headerFilter=true 이면 useFilterList 속성은 무시됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] headerFilter=true + useFilterList=true 로 그리드 생성 (col1~col4 Header Column 은 useFilter=true)\nheaderFilter=true 라 HeaderFilter 필터 행이 렌더되고 useFilter / useFilterList(FilterList) 관련 필터 UI 는 렌더되지 않음\n[절차] 무시 확인 버튼 클릭 (필터 영역 관찰)\n[확인] useFilter 컬럼에 FilterList 필터 아이콘 / 팝업이 없고 HeaderFilter 필터 행이 대신 존재 (options.useFilterList 도 false 로 미적용) → headerFilter=true 이므로 useFilterList 속성이 무시됨"', '', 'label1');

    // dataList 생성 (4행, col1~col4)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // headerFilter=true + useFilterList=true + useFilter 컬럼 + filterColumn 필터행을 가진 gridView 동적 생성
    await scwin.createIgnoreGridView();
}



// headerFilter=true + useFilterList=true 를 동시에 설정한 gridView 동적 생성
//  (createBasicGridView 는 useFilter / filterColumn / headerFilter 구성 불가 → 인라인 구성)
//  headerFilter=true 이므로 useFilterList(FilterList) 는 무시되고 HeaderFilter 필터 행이 렌더됨(defaultShowHeaderFilter=true 로 표시)
scwin.createIgnoreGridView = async function () {
    let grp_comp = document.querySelector('.tc_group_basic');
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' headerFilter="true" defaultShowHeaderFilter="true" useFilterList="true" dataList="data:dlt_bind" checkAllType="false" id="" style="width:560px;height:300px;">';
    s += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="130" style="" inputType="text" id="column1" value="col1" useFilter="true"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column2" value="col2" useFilter="true"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column3" value="col3" useFilter="true"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="column4" value="col4" useFilter="true"></w2:column>';
    s += '</w2:row>';
    s += '<w2:row style="" id="rowFilter">';
    s += '<w2:filterColumn width="130" style="" id="filterColumn1" value=""></w2:filterColumn>';
    s += '<w2:filterColumn width="130" style="" id="filterColumn2" value=""></w2:filterColumn>';
    s += '<w2:filterColumn width="130" style="" id="filterColumn3" value=""></w2:filterColumn>';
    s += '<w2:filterColumn width="*" style="" id="filterColumn4" value=""></w2:filterColumn>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="130" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 무시 확인 :
//  headerFilter=true 이면 useFilterList=true 를 줘도 무시됨을 상태 읽기로 확인.
//   - useFilter 컬럼에 FilterList 필터 아이콘(input.w2grid_customFilter_open) / FilterList 팝업(.w2grid_customFilter_list) 이 없음
//   - HeaderFilter 필터 행(tr.w2grid_header_filter) 이 대신 존재
//  (헤더 조작 등 사용자 액션은 별도 트리거 없이 상태 출력만 수행)
scwin.btn_checkIgnore_onclick = function (e) {
    let scb = wf_body_bottom.getObj("scwin");

    // 설정된 옵션값 (XML 에 useFilterList="true" 를 선언해도 headerFilter=true 라 적용되지 않아 옵션값이 false 로 유지됨)
    scb.setReturnValue("[옵션] useFilterList (XML 선언=true) 적용값 : " + target1.options.useFilterList + " / headerFilter : " + target1.options.headerFilter);

    // useFilter(FilterList) 관련 필터 아이콘 / 팝업 존재 여부
    let filterIcon = document.querySelector("[id*='target1_head_table'] input.w2grid_customFilter_open");
    let listPopup = document.querySelector(".w2grid_customFilter_list");
    scb.setReturnValue("useFilter 컬럼 필터 아이콘(input.w2grid_customFilter_open) 존재 : " + !!filterIcon + " / FilterList 팝업(.w2grid_customFilter_list) 존재 : " + !!listPopup);

    // HeaderFilter 필터 행 존재 여부
    let filterTr = document.querySelector("[id*='target1_head_table'] tr.w2grid_header_filter");
    scb.setReturnValue("HeaderFilter 필터 행(tr.w2grid_header_filter) 존재 : " + !!filterTr);
}
